-- ============================================================
-- Fix: Multiple Companies scope missing on production
-- Date: 2026-07-25
-- Root cause: The original export script only exported the
-- WorkflowDefinitions.CompanyId column. It missed:
--   1. ScopeType column (Global / Multiple / Single)
--   2. WorkflowDefinitionCompanies junction table rows
-- Because ScopeType wasn't set and CompanyId was NULL for the
-- "GL" workflows, the backend's ResolveWorkflowAsync treated them
-- as CompanyId==null => applies to ALL companies (see backend
-- WorkflowsController.cs ResolveWorkflowAsync: 
-- w.CompanyId == null matches every company).
-- This script restores the correct "Multiple" scope + company list
-- for the 4 affected workflows: 101-GL-GENERAL, 103-GL-LOGISTICS,
-- 107-GL-AST, 111-GL-L-AST.
-- 105-GL-IT and 109-GL-IT-AST are intentionally ScopeType='Global'
-- (CompanyId=NULL, no junction rows needed) — leave as-is.
-- ============================================================

USE MaterialRequestDB_App;
GO

-- ============================================================
-- STEP 1: Set ScopeType = 'Multiple' on the 4 affected workflows
-- ============================================================
UPDATE WorkflowDefinitions SET ScopeType = 'Multiple' WHERE Code = '101-GL-GENERAL';
UPDATE WorkflowDefinitions SET ScopeType = 'Multiple' WHERE Code = '103-GL-LOGISTICS';
UPDATE WorkflowDefinitions SET ScopeType = 'Multiple' WHERE Code = '107-GL-AST';
UPDATE WorkflowDefinitions SET ScopeType = 'Multiple' WHERE Code = '111-GL-L-AST';
GO

-- ============================================================
-- STEP 2: Clear any partial/duplicate junction rows for these 4
-- workflows first (safety, in case this script is re-run)
-- ============================================================
DELETE FROM WorkflowDefinitionCompanies
WHERE WorkflowDefinitionId IN (
    SELECT Id FROM WorkflowDefinitions
    WHERE Code IN ('101-GL-GENERAL','103-GL-LOGISTICS','107-GL-AST','111-GL-L-AST')
);
GO

-- ============================================================
-- STEP 3: Insert WorkflowDefinitionCompanies rows (from dev export)
-- ============================================================
GO

-- ============================================================
-- STEP 4: Verify
-- ============================================================
SELECT wd.Code, wd.Name, wd.ScopeType, wd.CompanyId,
       (SELECT COUNT(*) FROM WorkflowDefinitionCompanies wc WHERE wc.WorkflowDefinitionId = wd.Id) AS CompanyLinkCount
FROM WorkflowDefinitions wd
WHERE wd.Code IN ('101-GL-GENERAL','103-GL-LOGISTICS','107-GL-AST','111-GL-L-AST','105-GL-IT','109-GL-IT-AST')
ORDER BY wd.Code;

-- ============================================================
